import json

def main(state, input_data):
    inp = state.get('input') or {}
    if not isinstance(inp, dict):
        inp = {}
    action = inp.get('action') or 'ask'
    bill = inp.get('bill') or {}
    if isinstance(bill, str):
        try:
            bill = json.loads(bill)
        except Exception:
            bill = {}
    params = inp.get('params') or {}
    if not isinstance(params, dict):
        params = {}

    charges = bill.get('charges') or []
    slabs = []
    for c in charges:
        try:
            slabs.append([float(c.get('units')), float(c.get('rate'))])
        except Exception:
            pass
    if not slabs:
        slabs = [[100.0, 3.4], [100.0, 4.8], [1000000000.0, 7.7]]
    top_rate = slabs[-1][1]
    fixed = float(bill.get('fixed_charges') or 0)
    duty = float(bill.get('electricity_duty') or 0)
    units = bill.get('units_consumed')
    if units is None:
        units = sum([s[0] for s in slabs if s[0] < 100000000.0])
    units = float(units)

    def energy(u):
        total = 0.0
        left = u
        for w, rate in slabs:
            take = w if left > w else left
            if take < 0:
                take = 0
            total += take * rate
            left = left - take
            if left <= 0:
                break
        if left > 0:
            total += left * top_rate
        return total

    orig_energy = energy(units)
    t = bill.get('total_amount')
    orig_total = float(t) if t is not None else round(orig_energy + fixed + duty)
    blended = (orig_energy / units) if units > 0 else top_rate

    cut = float(params.get('cut') or 0)
    tod = bool(params.get('tod'))
    nu = units - cut
    if nu < 0:
        nu = 0
    e2 = energy(nu)
    if tod:
        e2 = e2 * 0.92
    wbill = round(e2 + fixed + duty)
    wsave = orig_total - wbill
    if wsave < 0:
        wsave = 0
    whatif = {'new_units': nu, 'new_bill': wbill, 'saving': wsave, 'yearly': wsave * 12}

    su = params.get('units')
    su = float(su) if su else units
    kw = round(su / 140.0 * 2) / 2.0
    if kw < 1:
        kw = 1.0
    if kw > 10:
        kw = 10.0
    cost = kw * 50000.0
    sub = 30000.0 if kw <= 1 else (60000.0 if kw <= 2 else 78000.0)
    net = cost - sub
    if net < 0:
        net = 0
    gen = kw * 140.0
    off = gen if gen < su else su
    ssave = round(off * blended)
    pay = (net / (ssave * 12.0)) if ssave > 0 else 0
    solar = {'kw': kw, 'cost': round(cost), 'subsidy': round(sub), 'net_cost': round(net),
             'monthly_saving': ssave, 'payback_years': round(pay, 1)}

    hist = bill.get('history') or []
    hv = []
    for h in hist:
        v = h[1] if isinstance(h, list) else h.get('units_consumed')
        if v is not None:
            hv.append(float(v))
    base = units
    if len(hv) > 1:
        past = hv[:-1][-6:]
        base = round(sum(past) / len(past))
    pct = round((units - base) / base * 100) if base > 0 else 0
    rates = [s[1] for s in slabs]
    max_rate = max(rates) if rates else 0
    parts = []
    for c in charges:
        parts.append({'label': c.get('slab') or c.get('label'),
                      'amount': c.get('amount'),
                      'top': float(c.get('rate') or 0) == max_rate})
    if fixed:
        parts.append({'label': '__fixed', 'amount': round(fixed), 'top': False})
    if duty:
        parts.append({'label': '__duty', 'amount': round(duty), 'top': False})
    spike = {'current_units': units, 'baseline_units': base, 'vs_average_pct': pct,
             'parts': parts, 'peer_percentile': 72}

    u = units
    gj = u <= 200
    tod_ok = u >= 300
    schemes = [
        {'name': 'PM Surya Ghar: Muft Bijli Yojana', 'code': 'pm_surya', 'eligible': True, 'status': 'eligible',
         'note_en': 'Rooftop-solar subsidy up to about Rs 78,000 for 3 kW; open to domestic consumers.',
         'note_te': 'మేడపై సోలార్‌కు కేంద్ర సబ్సిడీ (3kW వరకు ~₹78,000). గృహ వినియోగదారులకు.'},
        {'name': 'Gruha Jyothi (200 free units)', 'code': 'gruha_jyothi', 'eligible': gj, 'status': ('eligible' if gj else 'not'),
         'note_en': ('Free power for 200 units or fewer a month.' if gj else ('Usage ' + str(int(u)) + ' is above the 200-unit cap.')),
         'note_te': ('నెలకు ≤200 యూనిట్లు వాడే గృహాలకు ఉచిత విద్యుత్.' if gj else ('మీ వాడకం ' + str(int(u)) + ' — 200 పరిమితి దాటింది.'))},
        {'name': 'Time-of-Day tariff opt-in', 'code': 'tod', 'eligible': tod_ok, 'status': ('recommended' if tod_ok else 'optional'),
         'note_en': 'Lower rate in off-peak hours; useful for higher usage.',
         'note_te': 'ఆఫ్-పీక్ గంటల్లో తక్కువ రేటు; అధిక వాడకానికి ఉపయోగం.'}
    ]

    return {'action': action, 'whatif': whatif, 'solar': solar, 'spike': spike, 'schemes': schemes}

