import json

def main(state, input_data):
    inp = state.get('input') or {}
    if not isinstance(inp, dict):
        inp = {}
    action = inp.get('action') or 'ask'
    comp = state.get('compute') or {}
    if isinstance(comp, str):
        try:
            comp = json.loads(comp)
        except Exception:
            comp = {}

    if action == 'ask' or action == 'grievance':
        raw = state.get('answer.content') or state.get('answer.text') or ''
        obj = {}
        if isinstance(raw, str) and raw:
            txt = raw.strip()
            if txt.startswith('```'):
                txt = txt.strip('`')
                if txt[:4] == 'json':
                    txt = txt[4:]
            a = txt.find('{')
            b = txt.rfind('}')
            if a >= 0 and b > a:
                try:
                    obj = json.loads(txt[a:b + 1])
                except Exception:
                    obj = {}
        res = {'action': action, 'answer_te': obj.get('te') or '', 'answer_en': obj.get('en') or ''}
        if not res['answer_te'] and not res['answer_en']:
            res['answer_en'] = raw if isinstance(raw, str) else ''
        return json.dumps(res, ensure_ascii=False)

    if action == 'bundle':
        return json.dumps({'action': 'bundle',
                           'spike': comp.get('spike'),
                           'schemes': comp.get('schemes'),
                           'whatif': comp.get('whatif'),
                           'solar': comp.get('solar')}, ensure_ascii=False)

    out = {'action': action}
    data = comp.get(action)
    if isinstance(data, dict):
        for k in data:
            out[k] = data[k]
    elif data is not None:
        out['result'] = data
    return json.dumps(out, ensure_ascii=False)
